1→{
2→  "workflow": {
3→    "research": true
4→  }
5→}

1→output "waf_policy_name" {
2→  description = "WAF security policy name for this workspace"
3→  value       = google_compute_security_policy.waf_policy.name
4→}
5→

 1→resource "google_compute_security_policy" "waf_policy" {
 2→  name        = "waf-policy-${local.environment}"
 3→  description = "Política de seguridad WAF Liftit"
 4→
 5→  advanced_options_config {
 6→    log_level    = "VERBOSE"
 7→    json_parsing = "STANDARD"
 8→  }
 9→}
10→
11→resource "google_compute_security_policy_rule" "rules" {
12→  for_each        = local.waf_rules
13→  security_policy = google_compute_security_policy.waf_policy.name
14→  priority        = tonumber(each.key)
15→  action          = each.value.action
16→  preview         = each.value.preview
17→  description     = each.value.description
18→
19→  match {
20→    versioned_expr = lookup(each.value, "versioned_expr", null)
21→
22→    dynamic "config" {
23→      for_each = lookup(each.value, "src_ip_ranges", null) != null ? [1] : []
24→      content {
25→        src_ip_ranges = each.value.src_ip_ranges
26→      }
27→    }
28→
29→    dynamic "expr" {
30→      for_each = lookup(each.value, "expr", null) != null ? [1] : []
31→      content {
32→        expression = each.value.expr
33→      }
34→    }
35→  }
36→
37→  dynamic "rate_limit_options" {
38→    for_each = lookup(each.value, "rate_limit_options", null) != null ? [each.value.rate_limit_options] : []
39→    content {
40→      rate_limit_threshold {
41→        count        = rate_limit_options.value.rate_limit_threshold.count
42→        interval_sec = rate_limit_options.value.rate_limit_threshold.interval_sec
43→      }
44→      ban_duration_sec = rate_limit_options.value.ban_duration_sec
45→      ban_threshold {
46→        count        = rate_limit_options.value.ban_threshold.count
47→        interval_sec = rate_limit_options.value.ban_threshold.interval_sec
48→      }
49→      conform_action = "allow"
50→      exceed_action  = "deny(429)"
51→    }
52→  }
53→}
54→
55→resource "google_compute_security_policy_rule" "ip_whitelist" {
56→  count           = length(lookup(local.ip_whitelist, terraform.workspace, [])) > 0 ? 1 : 0
57→  security_policy = google_compute_security_policy.waf_policy.name
58→  priority        = 1000
59→  action          = "allow"
60→  preview         = false
61→  description     = "Permitir IPs de confianza"
62→
63→  match {
64→    versioned_expr = "SRC_IPS_V1"
65→    config {
66→      src_ip_ranges = local.ip_whitelist[terraform.workspace]
67→    }
68→  }
69→}
