508→module "gke-apps-load-balancer" {
509→  source               = "git::ssh://git@github.com/liftitapp/tf-modules.git//load-balancer"
510→  load_balancer_type   = "application"
511→  scope                = "global"
512→  load_balancer_scheme = "EXTERNAL_MANAGED"
513→
514→  certificate_manager_certificates = "//certificatemanager.googleapis.com/${local.map_id}"
515→
516→  frontend_config = {
517→    name     = "gke-apps"
518→    port     = 443
519→    protocol = "TCP"
520→  }
521→  balancing_mode            = "RATE"
522→  max_rate                  = 1000
523→  backends                  = local.expanded_backends
524→  create_dns_record         = false
525→  cloud_armor_policy        = null
526→  cloudflare_zone_id        = local.hosted_zone_id
527→  app_public_name           = "gke-apps-${terraform.workspace}"
528→  health_check_port         = 8080
529→  health_check_request_path = "/health"
530→  timeout_sec               = 300
531→}
